//! Native per-control validation uses the current supported required state.
use super::*;
fn start(html:&str,source:&str)->(Document,Forms,Page){let mut d=crate::html::parse(html);d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://control-validation.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);let out=p.start(&mut d,&mut f,&[Script{node:0,label:"Native control validation".into(),source:source.into()}]);assert_eq!(out.errors,0,"{}",p.report());(d,f,p)}
#[test]
fn control_validation_canonical_methods_messages_and_supported_required_states(){
 start("<form><input id=input name=q required><textarea id=area name=body required></textarea><select id=select name=choice required><option value=''>Pick</option><option value=ready>Ready</option></select><button id=button>Submit</button></form>","var ids=['input','area','select','button'],classes=[HTMLInputElement,HTMLTextAreaElement,HTMLSelectElement,HTMLButtonElement];for(var i=0;i<ids.length;i++){var x=document.getElementById(ids[i]),P=classes[i].prototype,d=Object.getOwnPropertyDescriptor(P,'validationMessage');if(!d||typeof d.get!=='function'||d.set!==undefined||!d.enumerable||!d.configurable||Object.prototype.hasOwnProperty.call(x,'validationMessage'))throw 'message descriptor';for(var key of ['checkValidity','reportValidity']){var m=Object.getOwnPropertyDescriptor(P,key);if(!m||typeof m.value!=='function'||m.value.length!==0||m.value.name!==key||!m.writable||!m.enumerable||!m.configurable)throw 'method descriptor';}var valid=i===3;if(x.checkValidity()!==valid||(x.validationMessage==='')!==valid)throw 'initial required '+ids[i];x.disabled=true;if(x.checkValidity()!==true||x.validationMessage!=='')throw 'barred';x.disabled=false;}var input=document.getElementById('input'),area=document.getElementById('area'),select=document.getElementById('select');input.value='Ready';area.value='Body';select.value='ready';if(!input.checkValidity()||!area.checkValidity()||!select.checkValidity()||input.validationMessage||area.validationMessage||select.validationMessage)throw 'current values';");
}
#[test]
fn control_validation_synchronous_trusted_invalid_cancellation_and_current_job(){
 let(_,_,mut p)=start("<form id=form><input id=input required><input id=other required></form>","var x=document.getElementById('input'),other=document.getElementById('other'),order='',events=0;x.addEventListener('invalid',function(e){if(e.target!==x||e.currentTarget!==x||!e.isTrusted||!e.cancelable||e.bubbles)throw 'invalid event';order+='I';events++;e.preventDefault();x.value='Repaired';Promise.resolve().then(function(){order+='M';});});order+='A';if(x.checkValidity()!==false||order!=='AI'||events!==1)throw 'sync result';if(!x.checkValidity()||x.validationMessage!==''||events!==1||other.value!=='')throw 'fresh candidate';x.value='';if(x.reportValidity()!==false||events!==2)throw 'canceled report';order+='Z';");assert_eq!(p.take_validation_report(),Some(None));
}
#[test]
fn control_validation_ownerless_radio_groups_checkbox_and_readonly_barriers(){
 start("<input id=a name=group type=radio required><input id=b name=group type=radio><input id=check type=checkbox required><input id=read required readonly><fieldset disabled><legend><input id=free required></legend><input id=off required></fieldset>","var a=document.getElementById('a'),b=document.getElementById('b'),c=document.getElementById('check');if(a.checkValidity()||b.checkValidity()||c.checkValidity()||document.getElementById('free').checkValidity())throw 'required ownerless';b.checked=true;c.checked=true;if(!a.checkValidity()||!b.checkValidity()||!c.checkValidity()||a.validationMessage||b.validationMessage||c.validationMessage)throw 'current checked group';for(var id of ['read','off']){var x=document.getElementById(id);x.addEventListener('invalid',function(){throw 'barred invalid';});if(!x.checkValidity()||!x.reportValidity()||x.validationMessage!=='')throw 'barred candidate';}");
}
#[test]
fn control_validation_barred_metadata_precedes_missing_or_unsupported_model_state(){
 start("<datalist><input id=listed required type=number><button id=button></button><textarea id=area required></textarea><select id=select required></select></datalist>","for(var id of ['listed','button','area','select']){var x=document.getElementById(id);x.addEventListener('invalid',function(){throw 'barred event';});if(x.willValidate||x.validationMessage!==''||!x.checkValidity()||!x.reportValidity())throw 'barred without model '+id;}var fresh=document.createElement('input');fresh.setAttribute('type','hidden');if(fresh.validationMessage!==''||!fresh.checkValidity()||!fresh.reportValidity())throw 'fresh barred metadata';");
}
#[test]
fn control_validation_concrete_brands_inert_and_unsupported_constraints_refuse(){
 start("<input id=input required><button id=button></button><select id=select></select><textarea id=area></textarea><input id=pattern pattern=x><input id=number type=number>","var classes=[HTMLInputElement,HTMLButtonElement,HTMLSelectElement,HTMLTextAreaElement],ids=['input','button','select','area'],tags=['input','button','select','textarea'];for(var i=0;i<ids.length;i++){var P=classes[i].prototype,wrong=document.getElementById(ids[(i+1)%4]),inert=document.implementation.createHTMLDocument('inert').createElement(tags[i]);for(var key of ['validationMessage','checkValidity','reportValidity']){var method=key==='validationMessage'?Object.getOwnPropertyDescriptor(P,key).get:P[key],denied=false;try{method.call(wrong);}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'concrete brand';denied=false;try{method.call(inert);}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied)throw 'inert backend';denied=false;try{method.call(Object.create(P));}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'forged receiver';}}var pattern=document.getElementById('pattern');if(pattern.validationMessage||!pattern.checkValidity()||!pattern.reportValidity())throw 'empty optional pattern';pattern.value='y';if(pattern.checkValidity()||pattern.validationMessage!=='Match the required pattern: unnamed field.')throw 'pattern mismatch';for(var id of ['number']){var x=document.getElementById(id);for(var key of ['validationMessage','checkValidity','reportValidity']){var denied=false;try{if(key==='validationMessage'){x.validationMessage;}else{x[key]();}}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied)throw 'unsupported constraint';}x.disabled=true;if(x.validationMessage!==''||!x.checkValidity()||!x.reportValidity())throw 'barred unsupported state';}");
}
#[test]
fn control_validation_author_shadows_delete_restore_and_readonly_message(){
 start("<input id=input required>","var x=document.getElementById('input'),P=HTMLInputElement.prototype,d=Object.getOwnPropertyDescriptor(P,'validationMessage'),check=P.checkValidity,report=P.reportValidity;x.validationMessage='own';if(!x.validationMessage)throw 'readonly';var denied=false;try{(function(){'use strict';x.validationMessage='own';})();}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'strict readonly';Object.defineProperty(x,'checkValidity',{value:'own',configurable:true});if(x.checkValidity!=='own'||check.call(x)!==false)throw 'own method shadow';delete x.checkValidity;Object.defineProperty(P,'checkValidity',{value:'prototype',configurable:true});if(x.checkValidity!=='prototype'||check.call(x)!==false)throw 'prototype method shadow';delete P.checkValidity;if(x.checkValidity!==undefined||check.call(x)!==false)throw 'method deletion';Object.defineProperty(P,'checkValidity',{value:check,writable:true,enumerable:true,configurable:true});Object.defineProperty(x,'validationMessage',{value:'own',configurable:true});if(x.validationMessage!=='own'||d.get.call(x)==='')throw 'message own shadow';delete x.validationMessage;if(x.validationMessage==='')throw 'message restore';x.value='Ready';if(!check.call(x)||!report.call(x)||d.get.call(x)!=='')throw 'saved canonical';");
}
#[test]
fn control_validation_checked_snapshot_refusal_and_message_copy_refusal_recover(){
 for mode in 0..4{
  let(mut d,mut f,mut p)=start("<input id=input name=q required>","var x=document.getElementById('input'),events=0;x.addEventListener('invalid',function(){events++;});");let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("input")).unwrap();let object=node_handle(node);let before=format!("{:?}",d.nodes);let value=f.controls[&node].value.text();let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.begin_native_control_validation(object,true);assert!(result.is_err(),"mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls[&node].value.text(),value);assert!(p.state.form_validations.is_empty()&&p.state.synthetic_dispatches.is_empty());assert!(p.take_validation_report().is_none());p.state.retained_limit=limit;p.begin_job();p.state.copy_work=0;assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_validation_message(object).is_err());p.begin_job();p.runtime.execute("if(events!==0||x.validationMessage===''||x.checkValidity()!==false||events!==1)throw 'fresh recovery';x.value='Ready';if(!x.checkValidity()||x.validationMessage!=='')throw 'valid recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
 }
}
#[test]
fn control_validation_nested_fatal_listener_keeps_committed_edit_and_unwinds(){
 let(mut d,mut f,mut p)=start("<form id=form><input id=input name=q required><input id=other required></form>","var x=document.getElementById('input'),other=document.getElementById('other'),form=document.getElementById('form');x.addEventListener('invalid',function(){other.checkValidity();x.value='Committed';for(var i=0;i<10000;i++){x.getAttribute('id');}});");let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("input")).unwrap();p.begin_job();p.state.host_work=1000;let error=p.runtime.execute("x.checkValidity();",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance"),"{error}");assert_eq!(f.controls[&node].value.text(),"Committed");assert!(p.state.form_validations.is_empty()&&p.state.synthetic_dispatches.is_empty()&&p.state.form_requests.is_empty());assert!(p.take_validation_report().is_none());p.begin_job();p.runtime.execute("if(!x.checkValidity()||x.validationMessage!=='')throw 'fatal recovery';other.value='Ready';if(!form.checkValidity())throw 'form recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
}
#[test]
fn control_validation_saved_child_methods_preserve_origin_authority(){
 let(mut d,mut f,mut p)=start("<body><input id=input required></body>","var x=document.getElementById('input'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var P=frame.contentWindow.HTMLInputElement.prototype,check=P.checkValidity,get=Object.getOwnPropertyDescriptor(P,'validationMessage').get;if(check.call(x)!==false||get.call(x)==='')throw 'saved control methods';");p.set_location(&crate::navigation::address("https://foreign-validation.test/",&crate::navigation::Location::home()).unwrap());for source in ["check.call(x)","get.call(x)"]{p.begin_job();let error=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert!(p.state.form_validations.is_empty());}p.set_location(&crate::navigation::address("https://control-validation.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();p.runtime.execute("x.value='Ready';if(!check.call(x)||get.call(x)!=='')throw 'saved recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
}
